/**
 * Regression: every privacy/cookie link generated by the route registry
 * must lead to a real, localized legal page. The policy copy already exists
 * under shared Polish slugs for PL, ES and EN; do not invent new routes.
 *
 * Run: node --experimental-strip-types scripts/test-legal-links.mjs
 */
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { buildRoutePath } from "../src/config/routes.ts";

const legalSlugs = {
  privacy: "polityka-prywatnosci",
  cookies: "polityka-cookies",
};
const cookieBanner = readFileSync(
  new URL("../src/components/commercial/CookieConsent.tsx", import.meta.url),
  "utf8",
);

for (const [key, slug] of Object.entries(legalSlugs)) {
  assert.match(
    cookieBanner,
    new RegExp(`buildRoutePath\\(["']${key}["'],\\s*locale\\)`),
    `Cookie banner must resolve ${key} via the shared route registry`,
  );
  assert.ok(
    existsSync(new URL(`../src/app/[locale]/${slug}/page.tsx`, import.meta.url)),
    `The legal page ${slug} must exist`,
  );
  for (const locale of ["pl", "es", "en"]) {
    assert.equal(
      buildRoutePath(key, locale),
      `/${locale}/${slug}`,
      `${locale} ${key} link must resolve to its published page`,
    );
  }
}

console.log("PASS: six published privacy/cookie links match the route registry and consent banner");
